// Package postgres writes `academy migrate-legacy`'s plan (internal/legacy/labsdb read it) into the platform database
// (queries.sql, generated by sqlc).
package postgres

import (
	"context"
	"database/sql"
	"fmt"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/legacy"
)

// Store implements legacy.Store.
type Store struct {
	db *sql.DB
}

var _ legacy.Store = (*Store)(nil)

// NewStore writes into the open platform database db.
func NewStore(db *sql.DB) *Store { return &Store{db: db} }

// Done is what earlier runs imported.
func (s *Store) Done(ctx context.Context) (legacy.Done, error) {
	rows, err := New(s.db).LegacyRows(ctx)
	if err != nil {
		return legacy.Done{}, err
	}
	d := legacy.Done{Attempts: map[int64]int64{}, Events: map[int64]bool{}}
	for _, r := range rows {
		switch r.Kind {
		case "attempt":
			d.Attempts[r.LegacyID] = r.NewID
		case "event":
			d.Events[r.LegacyID] = true
		}
	}
	return d, nil
}

// Apply writes the plan for user in one transaction.
func (s *Store) Apply(ctx context.Context, user int64, p legacy.Plan) (legacy.Report, error) {
	done, err := s.Done(ctx)
	if err != nil {
		return legacy.Report{}, err
	}
	ids := done.Attempts
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return legacy.Report{}, err
	}
	defer func() { _ = tx.Rollback() }()
	q := New(tx)
	var r legacy.Report
	for _, a := range p.Attempts {
		params := InsertAttemptParams{UserID: user, LabID: a.Lab, ContentHash: a.Hash, Status: a.Status,
			StartedAt: a.StartedAt, HintsUsed: int64(a.HintsUsed)}
		if a.FinishedAt != nil {
			params.FinishedAt = sql.NullTime{Time: *a.FinishedAt, Valid: true}
		}
		if s := legacy.Seconds(a.Seconds); s != nil {
			params.Seconds = sql.NullInt64{Int64: int64(*s), Valid: true}
		}
		if a.Status == "passed" {
			params.Xp = sql.NullInt64{Int64: int64(a.XP), Valid: true}
		}
		id, err := q.InsertAttempt(ctx, params)
		if err != nil {
			if a.Status == "running" {
				return legacy.Report{}, fmt.Errorf("attempt %d (%s) is still running in Phase 10, and a lab is "+
					"running here too: abandon one first: %w", a.ID, a.Lab, err)
			}
			return legacy.Report{}, fmt.Errorf("attempt %d: %w", a.ID, err)
		}
		if err := q.InsertLegacyRow(ctx, InsertLegacyRowParams{Kind: "attempt", LegacyID: a.ID, NewID: id}); err != nil {
			return legacy.Report{}, err
		}
		ids[a.ID] = id
		r.Attempts++
	}
	for _, st := range p.Steps {
		if err := q.InsertStepResult(ctx, InsertStepResultParams{AttemptID: ids[st.Attempt], StepID: st.Step,
			Passed: st.Passed, Detail: st.Detail, At: st.At}); err != nil {
			return legacy.Report{}, fmt.Errorf("step result: %w", err)
		}
		r.Steps++
	}
	for _, h := range p.Hints {
		if err := q.InsertHint(ctx, InsertHintParams{AttemptID: ids[h.Attempt], StepID: h.Step, Idx: int64(h.Index),
			At: h.At}); err != nil {
			return legacy.Report{}, fmt.Errorf("hint: %w", err)
		}
		r.Hints++
	}
	for _, e := range p.Events {
		data, err := legacy.Remap(e.Data, ids)
		if err != nil {
			return legacy.Report{}, fmt.Errorf("event %d: %w", e.ID, err)
		}
		id, err := q.InsertEvent(ctx, InsertEventParams{UserID: user, Kind: e.Kind, Subject: e.Subject,
			Data: data, At: e.At})
		if err != nil {
			return legacy.Report{}, fmt.Errorf("event %d: %w", e.ID, err)
		}
		if err := q.InsertLegacyRow(ctx, InsertLegacyRowParams{Kind: "event", LegacyID: e.ID, NewID: id}); err != nil {
			return legacy.Report{}, err
		}
		r.Events++
	}
	for _, a := range p.Awards {
		n, err := q.InsertAward(ctx, InsertAwardParams{UserID: user, BadgeID: a.Badge, AwardedAt: a.At})
		if err != nil {
			return legacy.Report{}, fmt.Errorf("award %s: %w", a.Badge, err)
		}
		r.Awards += int(n)
	}
	if err := tx.Commit(); err != nil {
		return legacy.Report{}, err
	}
	return r, nil
}
